      "fact": "get_household returned: customer_id C2044 (account holder), authorized_lines: ['L3005'], members: [{'name': 'Mia Whitfield', 'customer_id': 'C3001', 'line_id': 'L3005'}]."
    },
    {
      "source_id": "t0",
      "actor": "assistant",
      "role": "call",
      "fact": "Current move: get_line_details with line_id 'L3005'."
    }
